const escapeHtml = (s) => String(s).replace(/[&<>"']/g, (c) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
}[c]));

const html = (strings, ...values) =>
  strings.reduce((out, part, i) =>
    out + part + (i < values.length ? escapeHtml(values[i]) : ''), '');

const page = html`<h1>${title}</h1><ul>${rows.map((r) => r.name).join(', ')}</ul>`;

